"""Build the pinned Mednafen CD resampler and record software reference hashes.

The reference's coefficient table, buffer reader, volume matrix and resampler
functions are compiled unchanged. No Q2PSX implementation is linked or read.
These are software comparisons, not hardware capture fixtures.
"""
import argparse
import hashlib
from pathlib import Path
import subprocess

SOURCE_BLOB = "0ed59c322adababa0a2ac6165cd1c9b3aaeafc6f"

PREFIX = r'''
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>
#define INLINE static
typedef struct {
    int16_t ADPCM_ResampBuf[2][64];
    unsigned ADPCM_ResampCurPhase, ADPCM_ResampCurPos;
    struct { int16_t Samples[2][6048]; unsigned ReadPos; } AudioBuffer;
    uint8_t DecodeVolume[2][2];
    bool Muted;
} PS_CDC;
'''

DRIVER = r'''
static PS_CDC cdc;
int main(void) {
    unsigned kind, i, sector;
    puts("/* GPL-2.0-or-later software reference: Mednafen/Beetle PSX.");
    puts(" * Generated by generate_xa_reference.py; see README.md.");
    puts(" * This is not independent hardware output. */");
    puts("static const u64 xa_reference_hash[6][3] = {");
    for (kind = 0; kind < 6; kind++) {
        uint32_t rng = 0x12345678u + kind;
        memset(&cdc, 0, sizeof(cdc));
        cdc.DecodeVolume[0][0] = cdc.DecodeVolume[1][1] = 128;
        for (i = 0; i < 6048; i++) {
            int32_t l = 0, r = 0;
            switch (kind) {
            case 0: l = i == 0 ? 32767 : 0; r = i == 12 ? -32768 : 0; break;
            case 1: l = 1000; r = -1000; break;
            case 2: l = 32767; r = -32768; break;
            case 3: l = i & 1 ? 32767 : -32768; r = -l - 1; break;
            case 4:
                rng = rng * 1664525u + 1013904223u; l = (int16_t)(rng >> 16);
                rng = rng * 1664525u + 1013904223u; r = (int16_t)(rng >> 16); break;
            case 5: l = i % 37 < 18 ? 32767 : -32768; r = i % 31 < 15 ? -32768 : 32767; break;
            }
            cdc.AudioBuffer.Samples[0][i] = (int16_t)l;
            cdc.AudioBuffer.Samples[1][i] = (int16_t)r;
        }
        printf("    {");
        for (sector = 0; sector < 3; sector++) {
            uint64_t hash = UINT64_C(14695981039346656037);
            for (i = 0; i < 2352; i++) {
                int32_t samples[2]; unsigned ch;
                PS_CDC_GetCDAudio(&cdc, samples, 6);
                for (ch = 0; ch < 2; ch++) {
                    uint16_t v = (uint16_t)samples[ch];
                    hash = (hash ^ (v & 255)) * UINT64_C(1099511628211);
                    hash = (hash ^ (v >> 8)) * UINT64_C(1099511628211);
                }
            }
            if (cdc.AudioBuffer.ReadPos != (sector + 1) * 2016) return 2;
            printf("0x%016llxULL%s", (unsigned long long)hash, sector == 2 ? "" : ", ");
        }
        puts("},");
    }
    puts("};");
    return 0;
}
'''


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--source", type=Path, required=True)
    parser.add_argument("--work-dir", type=Path, required=True)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    raw = args.source.read_bytes()
    blob = hashlib.sha1(f"blob {len(raw)}\0".encode() + raw).hexdigest()
    if blob != SOURCE_BLOB:
        raise SystemExit("Expected cdc.c from Beetle PSX de6e32cf78f4403766167bfbe83f33074efeb83e")
    source = raw.decode("utf-8")
    notice = source[:source.index("#include")]
    start = source.index("static const int16_t CDADPCMImpulse")
    end = source.index("typedef struct XA_Subheader", start)
    work = args.work_dir.resolve()
    work.mkdir(parents=True, exist_ok=True)
    (work / "reference.c").write_text(notice + PREFIX + source[start:end] + DRIVER, encoding="utf-8")
    (work / "CMakeLists.txt").write_text(
        "cmake_minimum_required(VERSION 3.20)\nproject(xa_reference C)\n"
        "add_executable(xa_reference reference.c)\n", encoding="utf-8")
    with (work / "build.log").open("w", encoding="utf-8") as log:
        subprocess.run(["cmake", "-S", str(work), "-B", str(work / "build")], cwd=work,
                       stdout=log, stderr=subprocess.STDOUT, check=True)
        subprocess.run(["cmake", "--build", str(work / "build"), "--config", "Release", "--parallel", "4"],
                       cwd=work, stdout=log, stderr=subprocess.STDOUT, check=True)
    candidates = [work / "build/Release/xa_reference.exe", work / "build/xa_reference"]
    binary = next(p for p in candidates if p.is_file())
    expected = subprocess.check_output([str(binary)], cwd=work, text=True)
    output = Path(__file__).with_name("xa_resample_reference.h")
    if args.check:
        if output.read_text(encoding="utf-8") != expected:
            raise SystemExit("XA software reference differs from compiled upstream")
    else:
        output.write_text(expected, encoding="utf-8")
    print("Verified 6 signals x 3 sectors against compiled upstream CD resampling")


if __name__ == "__main__":
    main()
